# CLIENT MANAGER
class ClientManager:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if getattr(self, "_initialized", False):
            return
        self.cerebras = None
        self.exa = None
        self.tokenizer = None
        self.pg_pool: Optional[ThreadedConnectionPool] = None
        self.pg_dsn = None
        self._init_models()
        self._init_cache_backends()
        self._initialized = True

    def _init_models(self):
        if Cerebras and os.getenv("CEREBRAS_API_KEY"):
            self.cerebras = Cerebras(
                api_key=os.getenv("CEREBRAS_API_KEY"),
                timeout=config.REQUEST_TIMEOUT,
                max_retries=1
            )
        if tiktoken:
            self.tokenizer = tiktoken.get_encoding("gpt2")
        if Exa and os.getenv("EXA_API_KEY"):
            self.exa = Exa(
                api_key=os.getenv("EXA_API_KEY"),
                timeout=config.SEARCH_TIMEOUT
            )

    def _init_cache_backends(self):
        dsn_env = os.getenv("NEON_DATABASE_URL")
        if not dsn_env:
            raw = os.getenv("NEON_PSQL_DSN")
            if raw and raw.startswith("postgresql://"):
                dsn_env = raw
        if HAS_PG and dsn_env and dsn_env.startswith("postgresql://"):
            try:
                self.pg_dsn = dsn_env
                self.pg_pool = ThreadedConnectionPool(
                    minconn=1, maxconn=20, dsn=self.pg_dsn
                )
                self._ensure_pg_schema()
                logger.info("Postgres cache initialized (Neon).")
            except Exception as e:
                logger.warning(f"Postgres init failed: {e}")
                self.pg_pool = None

    def _ensure_pg_schema(self):
        conn = self.pg_pool.getconn()
        try:
            with conn, conn.cursor() as cur:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS ai_cache (
                        cache_key TEXT PRIMARY KEY,
                        value JSONB NOT NULL,
                        expire_at TIMESTAMPTZ NOT NULL
                    );
                """)
                cur.execute("CREATE INDEX IF NOT EXISTS idx_ai_cache_expire ON ai_cache (expire_at);")
        finally:
            self.pg_pool.putconn(conn)

clients = ClientManager()

# TOKEN COUNT
@lru_cache(maxsize=10000)
def count_tokens(text: str) -> int:
    if clients.tokenizer:
        return len(clients.tokenizer.encode(text))
    return max(1, len(text) // 4)

# SANITIZE / VALIDATE
def fast_sanitize(text: str) -> str:
    return bleach.clean(text or "", tags=[], strip=True).strip()

def fast_validate(query: str) -> bool:
    return bool(query and len(query) > 0)

# CACHE LAYER
class Cache:
    _mem_lock = threading.Lock()
    _mem_cache: Dict[str, Tuple[float, Dict[str, Any]]] = {}

    @staticmethod
    def _now_ts() -> float:
        return time.time()

    @staticmethod
    def _ttl_to_ts(ttl_seconds: int) -> float:
        return time.time() + ttl_seconds

    @classmethod
    def get(cls, key: str) -> Optional[Dict[str, Any]]:
        # Postgres cache
        if clients.pg_pool:
            try:
                conn = clients.pg_pool.getconn()
                try:
                    with conn, conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                        cur.execute(
                            "SELECT value FROM ai_cache WHERE cache_key=%s AND expire_at > NOW()",
                            (key,)
                        )
                        row = cur.fetchone()
                        if row and row.get("value"):
                            return row["value"]
                finally:
                    clients.pg_pool.putconn(conn)
            except Exception as e:
                logger.warning(f"PG cache get error: {e}")

        # Memory cache
        with cls._mem_lock:
            item = cls._mem_cache.get(key)
            if item:
                expire_ts, data = item
                if expire_ts > cls._now_ts():
                    return data
                else:
                    cls._mem_cache.pop(key, None)
        return None

    @classmethod
    def set(cls, key: str, value: Dict[str, Any], ttl_seconds: int = config.CACHE_TTL_SECONDS):
        # Postgres cache
        if clients.pg_pool:
            try:
                conn = clients.pg_pool.getconn()
                try:
                    with conn, conn.cursor() as cur:
                        expire_interval = f"INTERVAL '{ttl_seconds} seconds'"
                        cur.execute(
                            f"""
                            INSERT INTO ai_cache (cache_key, value, expire_at)
                            VALUES (%s, %s, NOW() + {expire_interval})
                            ON CONFLICT (cache_key)
                            DO UPDATE SET value = EXCLUDED.value, expire_at = EXCLUDED.expire_at
                            """,
                            (key, json.dumps(value))
                        )
                finally:
                    clients.pg_pool.putconn(conn)
            except Exception as e:
                logger.warning(f"PG cache set error: {e}")

        # Memory cache
        with cls._mem_lock:
            if len(cls._mem_cache) > 5000:
                cls._mem_cache.pop(next(iter(cls._mem_cache)))
            cls._mem_cache[key] = (cls._ttl_to_ts(ttl_seconds), value)

# EXA SEARCH
def exa_fast_search(query: str):
    return clients.exa.search_and_contents(
        query,
        num_results=config.MAX_SEARCH_RESULTS,
        text=True,
        use_autoprompt=True,
        type="auto",
        livecrawl=config.LIVECRAWL,
        text_contents_options={
            "max_characters": 50000,
            "include_html_tags": False
        },
    )

def process_results_fast(exa_results) -> Tuple[List[Dict[str, Any]], List[str]]:
    if not exa_results or not getattr(exa_results, "results", None):
        return [], []
    results = exa_results.results[:config.MAX_SEARCH_RESULTS]

    processed, contexts = [], []

    def proc(r):
        title = r.title or "No title"
        text = r.text or ""
        return {
            "title": title,
            "snippet": (text[:500] + ("..." if len(text) > 500 else "")) if text else "No content",
            "url": r.url
        }, f"Source: {title}\n{text[:5000]}"

    with ThreadPoolExecutor(max_workers=config.MAX_WORKERS) as ex:
        futs = [ex.submit(proc, r) for r in results]
        for f in as_completed(futs, timeout=5):
            try:
                p, c = f.result()
                processed.append(p)
                contexts.append(c)
            except Exception:
                pass

    return processed, contexts

